def validate(body: dict) -> list[str]:
    errors = []
    t = body.get('text')
    if not (isinstance(t, str) and t.strip()):
        errors.append('text is required')
    if 'max_points' in body:
        mp = body['max_points']
        if not (type(mp) is int and 1 <= mp <= 10):
            errors.append('max_points must be 1 to 10')
    return errors

def match(pattern: str, path: str) -> dict | None:
    a, b = pattern.strip('/').split('/'), path.strip('/').split('/')
    if len(a) != len(b):
        return None
    out = {}
    for x, y in zip(a, b):
        if x.startswith('{') and x.endswith('}'):
            out[x[1:-1]] = y
        elif x != y:
            return None
    return out

