def load_settings(env: dict) -> dict:
    if not env.get('API_KEY'):
        raise KeyError('API_KEY')
    return {'api_key': env['API_KEY'], 'model': env.get('MODEL', 'claude-haiku-4-5'), 'max_tokens': int(env.get('MAX_TOKENS', 800))}
